import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        // Bound to a large practical range to avoid overflow and out-of-funds issues
        uint256 amt = bound(amount, 1, type(uint128).max);

        // Fund the actor and have them deposit
        vm.deal(actor, amt);
        vm.prank(actor);
        (bool depositOk,) = address(c).call{value: amt}("");
