pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        // bound amount to avoid overflow and keep it admissible
        amount = bound(amount, 1, 100 ether);
        // deploy an adversarial receiver whose fallback always reverts
        Reverter reverter = new Reverter();
        address caller = address(reverter);
        // fund caller and deposit into c
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent, "deposit failed");
        // now withdraw: reference should revert, mutant does not
        bool ok;
        vm.prank(caller);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        // property: after a withdraw attempt by a reverting receiver, the caller's balance is unchanged
        assertTrue(!ok ? c.balances(caller) == amount : true);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

