pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount reasonable and ensure caller is not the zero address
        amount = bound(amount, 1, 1000 ether);
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));

        // Deploy a re-entrant attacker that calls withdraw again inside its receive
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // Fund attacker with some ETH so it can deposit
        vm.deal(attackerAddr, amount);
        vm.prank(attackerAddr);
        c.deposit{value: amount}();

        // Now attacker calls withdraw. The receive function of Attacker will
        // re-enter c.withdraw() before the original balances[attackerAddr] is zeroed.
        uint256 balanceBefore = c.balances(attackerAddr);
        bool success;
        try attacker.attack() {
            success = true;
        } catch {
            success = false;
        }

        // After a successful withdraw, balances[attackerAddr] MUST be 0.
        // The buggy version leaves stale balance because re-entrancy
        // spends the same funds multiple times without protection.
        if (success) {
            uint256 balanceAfter = c.balances(attackerAddr);
            assertEq(balanceAfter, 0);
        } else {
            // If it reverted, balances must be unchanged (no effect).
            assertEq(c.balances(attackerAddr), balanceBefore);
        }
    }
}

contract Attacker {
    C public target;
    bool private reentered;

    constructor(C _target) {
        target = _target;
        reentered = false;
    }

    function attack() external {
        require(!reentered, "already attacking");
        reentered = true;
        target.withdraw();
        reentered = false;
    }

    receive() external payable {
        if (address(target).balance >= target.balances(address(this)) && target.balances(address(this)) > 0) {
            // re-enter only once
            if (!reentered) {
                reentered = true;
                target.withdraw();
                reentered = false;
            }
        }
    }
}

