pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);

        // Record the ether sent to C by actor
        uint256 sent = depositAmount;
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool sentOk,) = address(c).call{value: depositAmount}("");
        require(sentOk, "deposit failed");

        // Record the ether successfully received by actor from withdraw
        uint256 received;
        ReentrantAttacker attacker = new ReentrantAttacker(c, withdrawAmount);
        vm.deal(address(attacker), 0);
        // First, deposit to attacker so it has a balance in C
        vm.deal(address(attacker), depositAmount);
        vm.prank(address(attacker));
        (bool depOk,) = address(c).call{value: depositAmount}("");
        require(depOk, "attacker deposit failed");
        uint256 balanceBefore = address(attacker).balance;
        vm.prank(address(attacker));
        try attacker.attack() { } catch { }
        received = address(attacker).balance - balanceBefore;

        // The general rule: no actor's balance after any sequence can exceed
        // (total sent by that actor to C) - (total ether successfully received by that actor from C).
        // Here we just check that the attacker's final mapping balance does not exceed
        // depositAmount - received (the amount still legitimately left).
        uint256 finalBalance = c.balances(address(attacker));
        uint256 maxExpected = depositAmount > received ? depositAmount - received : 0;
        assertTrue(finalBalance <= maxExpected);
    }
}

contract ReentrantAttacker {
    C public target;
    uint256 public amount;
    bool private reentered;

    constructor(C _target, uint256 _amount) {
        target = _target;
        amount = _amount;
    }

    function attack() external {
        target.withdraw();
    }

    receive() external payable {
        if (!reentered && address(target).balance >= amount) {
            reentered = true;
            target.withdraw();
        }
    }
}

